'use client';

import type { LineItem } from '@/lib/airtable';
import { Loader2 } from 'lucide-react';

const fmtMoney = (n: number | undefined): string =>
  typeof n === 'number' && !Number.isNaN(n)
    ? n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })
    : '-';

interface LineItemsTableProps {
  lineItems: LineItem[];
  loadingItems?: Set<string>;
  onFrequencyChange?: (itemId: string, frequency: number) => void;
  onRemoveItem?: (itemId: string) => void;
}

export default function LineItemsTable({ 
  lineItems = [], 
  loadingItems = new Set(),
  onFrequencyChange,
  onRemoveItem
}: LineItemsTableProps) {
  if (!lineItems || lineItems.length === 0) {
    return null;
  }

  const handleFrequencyChange = (itemId: string, service: string, frequency: string) => {
    if (onFrequencyChange && frequency) {
      onFrequencyChange(itemId, parseInt(frequency, 10));
    } else {
      alert(`TODO: Update ${service} frequency to ${frequency}`);
    }
  };

  const handleRemoveItem = (itemId: string, service: string) => {
    if (onRemoveItem) {
      onRemoveItem(itemId);
    } else {
      alert(`TODO: Delete ${service} from quote`);
    }
  };

  return (
    <div className="border border-gray-200 rounded-xl bg-brand-light-blue overflow-hidden">
      {/* Header */}
      <div className="bg-brand-navy text-white p-4">
        <div className="grid gap-4 text-sm font-medium" style={{ gridTemplateColumns: '1fr 120px 120px 120px 80px' }}>
          <div className="text-left">Service</div>
          <div className="text-center">Frequency</div>
          <div className="text-right">Standard Price</div>
          <div className="text-right">Member Price</div>
          <div></div>
        </div>
      </div>

      {/* Data Rows */}
      {lineItems.map((item, index) => {
        const chosenFreq = item.chosenFrequency?.toString() || '';
        const isLoading = loadingItems.has(item.id);
        const isLastItem = index === lineItems.length - 1;

        return (
          <div 
            key={item.id} 
            className={`p-4 bg-brand-light-blue relative transition-opacity ${
              !isLastItem ? 'border-b border-gray-200' : ''
            } ${isLoading ? 'opacity-60' : ''}`}
          >
            {isLoading && (
              <div className="absolute inset-0 flex items-center justify-center bg-white/50 z-10">
                <Loader2 className="h-5 w-5 animate-spin text-brand-navy" />
              </div>
            )}
            <div 
              className={`grid gap-4 text-sm items-center ${isLoading ? 'pointer-events-none' : ''}`} 
              style={{ gridTemplateColumns: '1fr 120px 120px 120px 80px' }}
            >
              <div className="font-medium text-brand-navy">{item.service}</div>
              <div className="text-center">
                <select 
                  value={chosenFreq || '1'}
                  onChange={(e) => handleFrequencyChange(item.id, item.service, e.target.value)}
                  disabled={isLoading}
                  className="w-12 border border-gray-300 rounded-lg px-2 py-1 text-sm bg-brand-light-cream text-brand-navy text-center disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {[...Array(12)].map((_, i) => (
                    <option key={i + 1} value={i + 1}>
                      {i + 1}
                    </option>
                  ))}
                </select>
              </div>
              <div className="text-right font-medium">{fmtMoney(item.alaCarteRate)}</div>
              <div className="text-right font-medium">{fmtMoney(item.handldRate)}</div>
              <div className="text-center">
                <button
                  onClick={() => handleRemoveItem(item.id, item.service)}
                  disabled={isLoading}
                  className="text-red-600 hover:text-red-800 text-sm px-2 py-1 rounded border border-red-300 hover:border-red-500 bg-brand-light-red disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  Remove
                </button>
              </div>
            </div>
          </div>
        );
      })}

    </div>
  );
}

