     4→import { useEffect, useMemo, useState } from 'react';
     5→import { useParams, useSearchParams } from 'next/navigation';
     6→import LineItemsTable from '../../components/LineItemsTable';
     7→import type { Quote, LineItem } from '@/lib/airtable';
     8→import { useToast } from '@/components/ui/use-toast';
     9→import { ConfirmationDialog } from '@/components/ui/confirmation-dialog';
    10→import { ServiceSelectionModal } from '@/components/ui/service-selection-modal';
    11→import { CTABanner } from '@/components/ui/cta-banner';
    12→import { LoadingScreen } from '@/components/ui/loading-screen';
    13→import { Logo } from '@/components/ui/logo';
    14→import { WelcomeBanner } from '@/components/ui/welcome-banner';
    15→import { useServices } from '@/hooks/useServices';
    16→import { useAddService } from '@/hooks/useAddService';
    17→import { DollarSign, Trophy, Lock, Plus, User, Mail, MapPin, Building, Home, TreePine } from 'lucide-react';
    18→
    19→const fmtMoney = (n: number | undefined): string =>
    20→  typeof n === 'number' && !Number.isNaN(n)
    21→    ? n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })
    22→    : '-';
    23→
    24→interface QuoteData {
    25→  quote: Quote;
    26→  lineItems: LineItem[];
    27→}
    28→
    29→/**
    30→ * Fetch quote data from our standard API endpoint
    31→ */
    32→async function fetchQuote(token: string): Promise<QuoteData> {
    33→  const url = `/api/quotes/${token}`;
    34→  
    35→  try {
    36→    const response = await fetch(url, { cache: 'no-store' });
    37→    
    38→    if (!response.ok) {
    39→      throw new Error(`Failed to fetch quote: ${response.status}`);
    40→    }
    41→    
    42→    const data = await response.json();
    43→    
    44→    // Basic sanity check - a quote payload should have these fields
    45→    if (!data || !data.quote) {
    46→      throw new Error('Invalid quote data received');
    47→    }
    48→    
    49→    // Handle undefined/null lineItems gracefully by converting to empty array
    50→    if (!Array.isArray(data.lineItems)) {
    51→      data.lineItems = [];
    52→    }
    53→    
    54→    return data;
    55→  } catch (error) {
    56→    if (error instanceof Error) {
    57→      throw error;
    58→    }
    59→    throw new Error('Failed to fetch quote');
    60→  }
    61→}
    62→
    63→function fmtPossessive(name: string | undefined): string {
    64→  if (!name) return 'Your';
    65→  return /s$/i.test(name) ? `${name}'` : `${name}'s`;
    66→}
    67→
    68→// Stripe booking URLs
    69→const STRIPE_MEMBER_BOOKING_URL = 'https://buy.stripe.com/aFaeVd4Rg8Ej89E5tc7wA01';
    70→const STRIPE_ALACARTE_BOOKING_URL = 'https://buy.stripe.com/9B600j2J85s79dI5tc7wA02';
    71→
    72→export default function QuoteViewerPage() {
    73→  const params = useParams();
    74→  const search = useSearchParams();
    75→  const token = params?.token as string;
    76→
    77→  const [loading, setLoading] = useState(true);
    78→  const [quoteData, setQuoteData] = useState<QuoteData | null>(null);
    79→  const [error, setError] = useState<string | null>(null);
    80→  const [loadingItems, setLoadingItems] = useState<Set<string>>(new Set());
    81→  interface DeleteConfirmationState {
    82→    isOpen: boolean;
    83→    itemId: string;
    84→    serviceName: string;
    85→  }
    86→
    87→  const [deleteConfirmation, setDeleteConfirmation] = useState<DeleteConfirmationState>({
    88→    isOpen: false,
    89→    itemId: '',
    90→    serviceName: ''
    91→  });
    92→  const [isServiceModalOpen, setIsServiceModalOpen] = useState(false);
    93→  const { toast } = useToast();
    94→
    95→  // Get existing service names for filtering
    96→  const existingServiceNames = quoteData?.lineItems?.map(item => item.service) || [];
    97→
    98→  // Hooks for service management
    99→  const { services, isLoading: servicesLoading, error: servicesError } = useServices(existingServiceNames);
   100→  const { isAdding, addService } = useAddService(
   101→    (serviceName: string, updatedData) => {
   102→      // Success callback
   103→      setIsServiceModalOpen(false);
   104→
   105→      if (!updatedData) {
   106→        toast({
   107→          title: "Warning",
   108→          description: `Failed to retrieve updated quote data after adding ${serviceName}. Please refresh the page.`,
   109→          variant: "destructive",
   110→        });
   111→        return;
   112→      }
   113→      
   114→      setQuoteData(updatedData);
   115→      
   116→      const newService = updatedData.lineItems.find(item => item.service === serviceName);
   117→      if (newService && (newService.handldRate === 0 || newService.alaCarteRate === 0)) {
   118→        toast({
   119→          title: "Service Added",
   120→          description: `${serviceName} has been added, but pricing data is still loading. Try refreshing if prices don't appear.`,
   121→          variant: "default",
   122→        });
   123→      } else {
   124→        toast({
   125→          title: "Success",
   126→          description: `${serviceName} added to your quote`,
   127→        });
   128→      }
   129→    },
   130→    (serviceName: string, error: string) => {
   131→      // Error callback
   132→      toast({
   133→        title: "Error",
   134→        description: error,
   135→        variant: "destructive",
   136→      });
   137→    }
   138→  );
   139→
   140→  // Calculate savings and totals client-side from line items with chosen frequencies
   141→  const { savings, alaCarteTotal } = useMemo(() => {
   142→    if (!quoteData?.lineItems) return { savings: 0, alaCarteTotal: 0 };
   143→    const selectedItems = quoteData.lineItems.filter(item => item.chosenFrequency && item.chosenFrequency > 0);
   144→    const standardTotal = selectedItems.reduce((sum, item) => sum + (item.alaCarteRate * (item.chosenFrequency || 0)), 0);
   145→    const memberTotal = selectedItems.reduce((sum, item) => sum + (item.handldRate * (item.chosenFrequency || 0)), 0);
   146→    return { 
   147→      savings: standardTotal - memberTotal,
   148→      alaCarteTotal: standardTotal
   149→    };
   150→  }, [quoteData?.lineItems]);
   151→
   152→  // Check if membership is available (3+ services)
   153→  const serviceCount = quoteData?.lineItems?.length || 0;
   154→  const membershipAvailable = serviceCount >= 3;
   155→  const servicesNeeded = Math.max(0, 3 - serviceCount);
   156→
   157→  useEffect(() => {
   158→    let mounted = true;
   159→    (async () => {
   160→      setLoading(true);
   161→      setError(null);
   162→      try {
   163→        if (!token) throw new Error('Missing token in URL.');
   164→        const data = await fetchQuote(token);
   165→        if (!mounted) return;
   166→        setQuoteData(data);
   167→      } catch (e: any) {
   168→        if (mounted) setError(e?.message || 'Failed to load quote');
   169→      } finally {
   170→        if (mounted) setLoading(false);
   171→      }
   172→    })();
   173→    return () => {
   174→      mounted = false;
   175→    };
   176→  }, [token]);
   177→
   178→  const handleFrequencyChange = async (itemId: string, frequency: number) => {
   179→    if (!quoteData) return;
   180→    
   181→    // Capture current state to avoid race conditions
   182→    const currentQuoteData = quoteData;
   183→    const originalItem = currentQuoteData.lineItems.find(item => item.id === itemId);
   184→    const originalFrequency = originalItem?.chosenFrequency;
   185→    
   186→    // Add item to loading state
   187→    setLoadingItems(prev => new Set(prev).add(itemId));
   188→    
   189→    try {
   190→      // Optimistically update the UI using captured state
   191→      const updatedLineItems = currentQuoteData.lineItems.map(item => 
   192→        item.id === itemId ? { ...item, chosenFrequency: frequency } : item
   193→      );
   194→      setQuoteData({ ...currentQuoteData, lineItems: updatedLineItems });
   195→      
   196→      const response = await fetch(`/api/quotes/${token}`, {
   197→        method: 'PUT',
   198→        headers: { 'Content-Type': 'application/json' },
   199→        body: JSON.stringify({
   200→          lineItems: [{ id: itemId, chosenFrequency: frequency }]
   201→        })
   202→      });
   203→      
   204→      if (response.ok) {
   205→        // Success toast
   206→        toast({
   207→          title: "Success",
   208→          description: "Frequency updated successfully",
   209→        });
   210→      } else {
   211→        throw new Error('Failed to update frequency');
   212→      }
   213→    } catch (error) {
   214→      console.error('Failed to update frequency:', error);
   215→      
   216→      // Revert using functional update to prevent race conditions
   217→      setQuoteData(prevData => {
   218→        if (!prevData) return prevData;
   219→        return {
   220→          ...prevData,
   221→          lineItems: prevData.lineItems.map(item => 
   222→            item.id === itemId ? { ...item, chosenFrequency: originalFrequency } : item
   223→          )
   224→        };
   225→      });
   226→      
   227→      // Error toast
   228→      toast({
   229→        title: "Error",
   230→        description: "Failed to update frequency. Please try again.",
   231→        variant: "destructive",
   232→      });
   233→    } finally {
   234→      // Remove item from loading state
   235→      setLoadingItems(prev => {
   236→        const newSet = new Set(prev);
   237→        newSet.delete(itemId);
   238→        return newSet;
   239→      });
   240→    }
   241→  };
   242→
   243→  const handleDeleteItem = (itemId: string) => {
   244→    if (!quoteData) return;
   245→    
   246→    const itemToDelete = quoteData.lineItems.find(item => item.id === itemId);
   247→    const serviceName = itemToDelete?.service || 'Service';
   248→    
   249→    // Show confirmation dialog
   250→    setDeleteConfirmation({
   251→      isOpen: true,
   252→      itemId,
   253→      serviceName
   254→    });
   255→  };
   256→
   257→  const confirmDelete = async () => {
   258→    if (!quoteData) return;
   259→    
   260→    const { itemId, serviceName } = deleteConfirmation;
   261→    
   262→    // Close the confirmation dialog
   263→    setDeleteConfirmation({ isOpen: false, itemId: '', serviceName: '' });
