   265→    // Capture current state to avoid race conditions
   266→    const currentQuoteData = quoteData;
   267→    const originalLineItems = [...currentQuoteData.lineItems];
   268→    
   269→    // Add item to loading state
   270→    setLoadingItems(prev => new Set(prev).add(itemId));
   271→    
   272→    try {
   273→      // Optimistically remove the item from UI using captured state
   274→      const updatedLineItems = originalLineItems.filter(item => item.id !== itemId);
