   290→          title: "Success",
   291→          description: `${serviceName} removed successfully`,
   292→        });
   293→      } else {
   294→        throw new Error('Failed to delete item');
   295→      }
   296→    } catch (error) {
   297→      console.error('Failed to delete item:', error);
   298→      
   299→      // Revert using captured original state to prevent race conditions
   300→      setQuoteData(prevData => {
   301→        if (!prevData) return prevData;
   302→        // Only revert if the current state still has the item removed
   303→        const currentItemExists = prevData.lineItems.some(item => item.id === itemId);
   304→        if (!currentItemExists) {
   305→          return { ...prevData, lineItems: originalLineItems };
   306→        }
   307→        return prevData;
   308→      });
   309→      
   310→      // Error toast
   311→      toast({
   312→        title: "Error",
   313→        description: `Failed to remove ${serviceName}. Please try again.`,
   314→        variant: "destructive",
   315→      });
   316→    } finally {
   317→      // Remove item from loading state
   318→      setLoadingItems(prev => {
   319→        const newSet = new Set(prev);
   320→        newSet.delete(itemId);
   321→        return newSet;
   322→      });
   323→    }
   324→  };
   325→
   326→  const handleAddService = async (serviceName: string) => {
   327→    if (!token) return;
   328→    await addService(serviceName, token);
   329→  };
   330→
   331→  const handleMemberBooking = () => {
