   333→    const cancelUrl = encodeURIComponent(`${window.location.origin}/q/${token}?cancelled=true`);
   334→    window.location.href = `${STRIPE_MEMBER_BOOKING_URL}?success_url=${successUrl}&cancel_url=${cancelUrl}`;
   335→  };
   336→
   337→  const handleAlaCarteBooking = () => {
   338→    const successUrl = encodeURIComponent(`${window.location.origin}/q/${token}?success=alacarte`);
   339→    const cancelUrl = encodeURIComponent(`${window.location.origin}/q/${token}?cancelled=true`);
   340→    // Convert total from dollars to cents for Stripe
