// app/q/[token]/page.tsx
'use client';

import { useEffect, useMemo, useState } from 'react';
import { useParams, useSearchParams } from 'next/navigation';
import LineItemsTable from '../../components/LineItemsTable';
import type { Quote, LineItem } from '@/lib/airtable';
import { useToast } from '@/components/ui/use-toast';
import { ConfirmationDialog } from '@/components/ui/confirmation-dialog';
import { ServiceSelectionModal } from '@/components/ui/service-selection-modal';
import { CTABanner } from '@/components/ui/cta-banner';
import { LoadingScreen } from '@/components/ui/loading-screen';
import { Logo } from '@/components/ui/logo';
import { WelcomeBanner } from '@/components/ui/welcome-banner';
import { useServices } from '@/hooks/useServices';
import { useAddService } from '@/hooks/useAddService';
import { DollarSign, Trophy, Lock, Plus, User, Mail, MapPin, Building, Home, TreePine } from 'lucide-react';

const fmtMoney = (n: number | undefined): string =>
  typeof n === 'number' && !Number.isNaN(n)
    ? n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })
    : '-';

interface QuoteData {
  quote: Quote;
  lineItems: LineItem[];
}

/**
 * Fetch quote data from our standard API endpoint
 */
async function fetchQuote(token: string): Promise<QuoteData> {
  const url = `/api/quotes/${token}`;

  try {
    const response = await fetch(url, { cache: 'no-store' });

    if (!response.ok) {
      throw new Error(`Failed to fetch quote: ${response.status}`);
    }

    const data = await response.json();

    // Basic sanity check - a quote payload should have these fields
    if (!data || !data.quote) {
      throw new Error('Invalid quote data received');
    }

    // Handle undefined/null lineItems gracefully by converting to empty array
    if (!Array.isArray(data.lineItems)) {
      data.lineItems = [];
    }

    return data;
  } catch (error) {
    if (error instanceof Error) {
      throw error;
    }
    throw new Error('Failed to fetch quote');
  }
}

function fmtPossessive(name: string | undefined): string {
  if (!name) return 'Your';
  return /s$/i.test(name) ? `${name}'` : `${name}'s`;
}

// Stripe booking URLs
const STRIPE_MEMBER_BOOKING_URL = 'https://buy.stripe.com/aFaeVd4Rg8Ej89E5tc7wA01';
const STRIPE_ALACARTE_BOOKING_URL = 'https://buy.stripe.com/9B600j2J85s79dI5tc7wA02';

export default function QuoteViewerPage() {
  const params = useParams();
  const search = useSearchParams();
  const token = params?.token as string;

  const [loading, setLoading] = useState(true);
  const [quoteData, setQuoteData] = useState<QuoteData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loadingItems, setLoadingItems] = useState<Set<string>>(new Set());
  interface DeleteConfirmationState {
    isOpen: boolean;
    itemId: string;
    serviceName: string;
  }

  const [deleteConfirmation, setDeleteConfirmation] = useState<DeleteConfirmationState>({
    isOpen: false,
    itemId: '',
    serviceName: ''
  });
  const [isServiceModalOpen, setIsServiceModalOpen] = useState(false);
  const { toast } = useToast();

  // Get existing service names for filtering
  const existingServiceNames = quoteData?.lineItems?.map(item => item.service) || [];

  // Hooks for service management
  const { services, isLoading: servicesLoading, error: servicesError } = useServices(existingServiceNames);
  const { isAdding, addService } = useAddService(
    (serviceName: string, updatedData) => {
      // Success callback
      setIsServiceModalOpen(false);

      if (!updatedData) {
        toast({
          title: "Warning",
          description: `Failed to retrieve updated quote data after adding ${serviceName}. Please refresh the page.`,
          variant: "destructive",
        });
        return;
      }

      setQuoteData(updatedData);

      const newService = updatedData.lineItems.find(item => item.service === serviceName);
      if (newService && (newService.handldRate === 0 || newService.alaCarteRate === 0)) {
        toast({
          title: "Service Added",
          description: `${serviceName} has been added, but pricing data is still loading. Try refreshing if prices don't appear.`,
          variant: "default",
        });
      } else {
        toast({
          title: "Success",
          description: `${serviceName} added to your quote`,
        });
      }
    },
    (serviceName: string, error: string) => {
      // Error callback
      toast({
        title: "Error",
        description: error,
        variant: "destructive",
      });
    }
  );

  // Calculate savings and totals client-side from line items with chosen frequencies
  const { savings, alaCarteTotal } = useMemo(() => {
    if (!quoteData?.lineItems) return { savings: 0, alaCarteTotal: 0 };
    const selectedItems = quoteData.lineItems.filter(item => item.chosenFrequency && item.chosenFrequency > 0);
    const standardTotal = selectedItems.reduce((sum, item) => sum + (item.alaCarteRate * (item.chosenFrequency || 0)), 0);
    const memberTotal = selectedItems.reduce((sum, item) => sum + (item.handldRate * (item.chosenFrequency || 0)), 0);
    return { 
      savings: standardTotal - memberTotal,
      alaCarteTotal: standardTotal
    };
  }, [quoteData?.lineItems]);

  // Check if membership is available (3+ services)
  const serviceCount = quoteData?.lineItems?.length || 0;
  const membershipAvailable = serviceCount >= 3;
  const servicesNeeded = Math.max(0, 3 - serviceCount);

  useEffect(() => {
    let mounted = true;
    (async () => {
      setLoading(true);
      setError(null);
      try {
        if (!token) throw new Error('Missing token in URL.');
        const data = await fetchQuote(token);
        if (!mounted) return;
        setQuoteData(data);
      } catch (e: any) {
        if (mounted) setError(e?.message || 'Failed to load quote');
      } finally {
        if (mounted) setLoading(false);
      }
    })();
    return () => {
      mounted = false;
    };
  }, [token]);

  const handleFrequencyChange = async (itemId: string, frequency: number) => {
    if (!quoteData) return;

    // Capture current state to avoid race conditions
    const currentQuoteData = quoteData;
    const originalItem = currentQuoteData.lineItems.find(item => item.id === itemId);
    const originalFrequency = originalItem?.chosenFrequency;

    // Add item to loading state
    setLoadingItems(prev => new Set(prev).add(itemId));

    try {
      // Optimistically update the UI using captured state
      const updatedLineItems = currentQuoteData.lineItems.map(item => 
        item.id === itemId ? { ...item, chosenFrequency: frequency } : item
      );
      setQuoteData({ ...currentQuoteData, lineItems: updatedLineItems });

      const response = await fetch(`/api/quotes/${token}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          lineItems: [{ id: itemId, chosenFrequency: frequency }]
        })
      });

      if (response.ok) {
        // Success toast
        toast({
          title: "Success",
          description: "Frequency updated successfully",
        });
      } else {
        throw new Error('Failed to update frequency');
      }
    } catch (error) {
      console.error('Failed to update frequency:', error);

      // Revert using functional update to prevent race conditions
      setQuoteData(prevData => {
        if (!prevData) return prevData;
        return {
          ...prevData,
          lineItems: prevData.lineItems.map(item => 
            item.id === itemId ? { ...item, chosenFrequency: originalFrequency } : item
          )
        };
      });

      // Error toast
      toast({
        title: "Error",
        description: "Failed to update frequency. Please try again.",
        variant: "destructive",
      });
    } finally {
      // Remove item from loading state
      setLoadingItems(prev => {
        const newSet = new Set(prev);
        newSet.delete(itemId);
        return newSet;
      });
    }
  };

  const handleDeleteItem = (itemId: string) => {
    if (!quoteData) return;

    const itemToDelete = quoteData.lineItems.find(item => item.id === itemId);
    const serviceName = itemToDelete?.service || 'Service';

    // Show confirmation dialog
    setDeleteConfirmation({
      isOpen: true,
      itemId,
      serviceName
    });
  };

  const confirmDelete = async () => {
    if (!quoteData) return;

    const { itemId, serviceName } = deleteConfirmation;

    // Close the confirmation dialog
    setDeleteConfirmation({ isOpen: false, itemId: '', serviceName: '' });

    // Capture current state to avoid race conditions
    const currentQuoteData = quoteData;
    const originalLineItems = [...currentQuoteData.lineItems];

    // Add item to loading state
    setLoadingItems(prev => new Set(prev).add(itemId));

    try {
      // Optimistically remove the item from UI using captured state
      const updatedLineItems = originalLineItems.filter(item => item.id !== itemId);
      setQuoteData({ ...currentQuoteData, lineItems: updatedLineItems });

      const response = await fetch(`/api/quotes/${token}`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ itemId })
      });

      if (response.ok) {
        const data = await response.json();
        // Update with the fresh data from server
        setQuoteData({ quote: data.quote, lineItems: data.lineItems });

        // Success toast
        toast({
          title: "Success",
          description: `${serviceName} removed successfully`,
        });
      } else {
        throw new Error('Failed to delete item');
      }
    } catch (error) {
      console.error('Failed to delete item:', error);

      // Revert using captured original state to prevent race conditions
      setQuoteData(prevData => {
        if (!prevData) return prevData;
        // Only revert if the current state still has the item removed
        const currentItemExists = prevData.lineItems.some(item => item.id === itemId);
        if (!currentItemExists) {
          return { ...prevData, lineItems: originalLineItems };
        }
        return prevData;
      });

      // Error toast
      toast({
        title: "Error",
        description: `Failed to remove ${serviceName}. Please try again.`,
        variant: "destructive",
      });
    } finally {
      // Remove item from loading state
      setLoadingItems(prev => {
        const newSet = new Set(prev);
        newSet.delete(itemId);
        return newSet;
      });
    }
  };

  const handleAddService = async (serviceName: string) => {
    if (!token) return;
    await addService(serviceName, token);
  };

  const handleMemberBooking = () => {
    const successUrl = encodeURIComponent(`${window.location.origin}/q/${token}?success=member`);
    const cancelUrl = encodeURIComponent(`${window.location.origin}/q/${token}?cancelled=true`);
    window.location.href = `${STRIPE_MEMBER_BOOKING_URL}?success_url=${successUrl}&cancel_url=${cancelUrl}`;
  };

  const handleAlaCarteBooking = () => {
    const successUrl = encodeURIComponent(`${window.location.origin}/q/${token}?success=alacarte`);
    const cancelUrl = encodeURIComponent(`${window.location.origin}/q/${token}?cancelled=true`);
    // Convert total from dollars to cents for Stripe
    const priceInCents = Math.round(alaCarteTotal * 100);
    window.location.href = `${STRIPE_ALACARTE_BOOKING_URL}?success_url=${successUrl}&cancel_url=${cancelUrl}${priceInCents > 0 ? `&amount=${priceInCents}` : ''}`;
  };

  if (loading) {
    return <LoadingScreen message="Loading your quote..." />;
  }
  if (error) {
    return (
      <main className="p-6">
        <pre className="whitespace-pre-wrap rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">
          {error}
        </pre>
      </main>
    );
  }
  if (!quoteData) {
    return <main className="p-6">No quote found.</main>;
  }

  const { quote, lineItems } = quoteData;
  const pageTitle = `${fmtPossessive(quote.firstName)} Handld Quote`;

  return (
    <>
      {/* Welcome Banner */}
      <WelcomeBanner />

      <main className="mx-auto max-w-4xl px-6 py-8 text-brand-navy mt-20">
        {/* Header with Logo */}
      <header className="mb-4">
        <div className="flex items-center gap-4 mb-4">
          {/* Logo */}
          <div className="flex-shrink-0">
            <Logo size={96} />
          </div>

          {/* Quote Title */}
          <div className="flex-1">
            <h1 className="text-3xl font-bold mb-1 text-brand-navy">
              {pageTitle}
            </h1>
            {quote.quoteId && (
              <div className="text-sm text-brand-navy">
                Quote ID: {quote.quoteId}
              </div>
            )}
          </div>
        </div>
      </header>


      {/* Customer Information - Condensed */}
      <section className="mb-4">
        <div className="border border-gray-200 rounded-xl p-3 bg-brand-light-cream shadow-md">
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {quote.firstName && quote.lastName && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600 flex items-center gap-1">
                  <User className="h-3 w-3" />
                  <span>Name</span>
                </div>
                <div className="text-base font-medium text-brand-navy">
                  {quote.firstName} {quote.lastName}
                </div>
              </div>
            )}

            {quote.email && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600 flex items-center gap-1">
                  <Mail className="h-3 w-3" />
                  <span>Email</span>
                </div>
                <div className="text-base text-brand-navy">
                  {quote.email}
                </div>
              </div>
            )}

            {quote.city && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600 flex items-center gap-1">
                  <MapPin className="h-3 w-3" />
                  <span>City</span>
                </div>
                <div className="text-base text-brand-navy">
                  {quote.city}
                </div>
              </div>
            )}

            {quote.stories && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600 flex items-center gap-1">
                  <Building className="h-3 w-3" />
                  <span>Stories</span>
                </div>
                <div className="text-base text-brand-navy">
                  {quote.stories}
                </div>
              </div>
            )}

            {quote.squareFootage && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600 flex items-center gap-1">
                  <Home className="h-3 w-3" />
                  <span>Square Footage</span>
                </div>
                <div className="text-base text-brand-navy">
                  {quote.squareFootage}
                </div>
              </div>
            )}

            {quote.lotSize && (
              <div>
                <div className="text-xs font-medium uppercase tracking-wide text-gray-600 flex items-center gap-1">
                  <TreePine className="h-3 w-3" />
                  <span>Lot Size</span>
                </div>
                <div className="text-base text-brand-navy">
                  {quote.lotSize}
                </div>
              </div>
            )}
          </div>
        </div>
      </section>


      {/* Services */}
      <section className="mb-4">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-2xl font-bold text-brand-navy">Services</h2>
          <button
            onClick={() => setIsServiceModalOpen(true)}
            className="text-sm px-4 py-2 rounded-full border border-brand-navy text-brand-navy bg-brand-light-blue hover:bg-brand-cream transition-all duration-300 flex items-center gap-1"
          >
            <Plus className="h-4 w-4" />
            <span>Add Service</span>
          </button>
        </div>
        <div className="shadow-md rounded-xl overflow-hidden">
          <LineItemsTable 
            lineItems={lineItems}
            loadingItems={loadingItems} 
            onFrequencyChange={handleFrequencyChange}
            onRemoveItem={handleDeleteItem}
          />
        </div>
      </section>

      {/* Buttons */}
      <section className="space-y-4">
        {/* Savings Highlight or CTA */}
        {membershipAvailable && savings > 0 ? (
          <div className="relative overflow-hidden bg-gradient-to-r from-green-400 via-emerald-400 to-teal-400 rounded-xl p-5 shadow-xl">
            <div className="absolute inset-0 bg-gradient-to-r from-green-400/20 via-emerald-400/20 to-teal-400/20 animate-pulse"></div>
            <div className="relative flex items-center justify-between">
              <div className="flex items-center gap-4">
                <Trophy className="h-8 w-8 text-white filter drop-shadow-md" />
                <div>
                  <p className="font-bold text-xl text-white drop-shadow-md">Your Handld Member Savings: {fmtMoney(savings)}!</p>
                  <p className="text-sm text-white/90 mt-1">Lock in these savings with Handld Membership!</p>
                </div>
              </div>
            </div>
          </div>
        ) : !membershipAvailable && (
          <CTABanner message={`Add ${servicesNeeded} more service${servicesNeeded === 1 ? '' : 's'} to unlock Handld Membership and save 30%!`} />
        )}

        <div className="flex flex-col sm:flex-row gap-4">
          <button
            onClick={handleMemberBooking}
            disabled={!membershipAvailable}
            className={`flex-1 rounded-full py-4 px-8 text-lg font-semibold transition-all duration-200 shadow-lg ${
              membershipAvailable
                ? 'text-white bg-brand-navy hover:bg-opacity-90 cursor-pointer'
                : 'text-gray-400 bg-gray-200 cursor-not-allowed opacity-60'
            }`}
          >
            {membershipAvailable ? (savings > 0 ? `Book Handld Membership — Save ${fmtMoney(savings)}` : 'Book Handld Membership — Save 30%') : 'Membership requires 3+ services'}
          </button>
          <button
            onClick={handleAlaCarteBooking}
            disabled={alaCarteTotal === 0}
            className={`flex-1 rounded-full py-4 px-8 text-lg font-medium border-2 transition-all duration-200 ${
              alaCarteTotal > 0
                ? 'border-brand-navy text-brand-navy bg-brand-light-blue hover:bg-brand-cream cursor-pointer'
                : 'border-gray-300 text-gray-400 bg-gray-100 cursor-not-allowed opacity-60'
            }`}
          >
            {alaCarteTotal > 0 ? `Book with Standard Pricing — ${fmtMoney(alaCarteTotal)}` : 'Select services to book'}
          </button>
        </div>
      </section>

      {/* Confirmation Dialog */}
      <ConfirmationDialog
        isOpen={deleteConfirmation.isOpen}
        title="Remove Service"
        message={`Are you sure you want to remove "${deleteConfirmation.serviceName}" from your quote? This action cannot be undone.`}
        confirmLabel="Remove"
        cancelLabel="Cancel"
        variant="danger"
        onConfirm={confirmDelete}
        onCancel={() => setDeleteConfirmation({ isOpen: false, itemId: '', serviceName: '' })}
      />

      {/* Service Selection Modal */}
      <ServiceSelectionModal
        isOpen={isServiceModalOpen}
        onClose={() => setIsServiceModalOpen(false)}
        onSelectService={handleAddService}
        services={services}
        isLoading={servicesLoading}
        error={servicesError}
        isAddingService={isAdding}
      />
      </main>
    </>
  );
}
